import java.nio.file.*;import javax.swing.*;import java.util.*;
public class TreeDesktopTest {
 static void check(boolean ok,String label){if(!ok)throw new AssertionError(label);}
 interface Condition{boolean get();}static void await(Condition c)throws Exception{for(int i=0;i<400;i++){boolean[] done={false};SwingUtilities.invokeAndWait(()->done[0]=c.get());if(done[0])return;Thread.sleep(50);}throw new AssertionError("Tree UI timed out");}
 static java.util.List<JComboBox<?>> choices(GraphEditor editor){java.util.List<JComboBox<?>> boxes=new ArrayList<>();for(var c:editor.properties.getComponents())if(c instanceof JComboBox<?> box)boxes.add(box);return boxes;}
 public static void main(String[] args)throws Exception{TerraForge.theme();TerraForge[] app=new TerraForge[1];Path file=Files.createTempFile("tree-ui-project-",".terra");SwingUtilities.invokeAndWait(()->{app[0]=new TerraForge();app[0].setVisible(true);});try{
  await(()->!app[0].busy&&app[0].world!=null);SwingUtilities.invokeAndWait(()->{var a=app[0];a.openNodes();var e=a.graphEditor;e.graph=TreeLibrary.template();e.selected=3;e.inspector();check(choices(e).size()==3,"library/group/variant dropdowns");choices(e).get(1).setSelectedIndex(1);check(e.graph.nodes.get(3).p("group")==1&&e.graph.nodes.get(3).p("variant")==0,"group selection resets exact variant");choices(e).get(1).setSelectedIndex(0);choices(e).get(2).setSelectedIndex(20);check(TreeLibrary.selected(e.graph.nodes.get(3)).id==20,"explicit variant selection");e.mapSize.setSelectedItem("128");a.dirty=false;a.buildGraph(e.graph.copy());});
  await(()->!app[0].busy&&!app[0].world.environment.trees.isEmpty());SwingUtilities.invokeAndWait(()->{var a=app[0];for(var p:a.world.environment.trees)check(p.tree()==20,"built forest does not mix variants");a.map.terrainImage();check(a.world.treeHeights!=null,"forest canopy rendered");a.saveTo(file.toFile());});await(()->!app[0].busy&&!app[0].dirty);SwingUtilities.invokeAndWait(()->app[0].load(file.toFile(),false));await(()->!app[0].busy);SwingUtilities.invokeAndWait(()->{var a=app[0];check(a.world.environment.trees.size()>0&&a.world.graph.nodes.get(3).p("variant")==20,"forest and selected variety restored");});
  System.out.println("PASS: tree library/group/variant controls, fixed-variant build, canopy preview and saved forest restoration");
 }finally{SwingUtilities.invokeAndWait(()->app[0].dispose());Files.deleteIfExists(file);}System.exit(0);}
}
